fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    debug_assert!(vals_2.len() == n && conds_1.len() == n && conds_2.len() == n,
        "All input slices must have the same length");

    // Clear any existing contents and prepare for n elements
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        let value = if c1 && c2 {
            // both true: average
            (vals_1[i] + vals_2[i]) / 2
        } else if c1 {
            // only first
            vals_1[i]
        } else {
            // only second
            vals_2[i]
        };
        avgs.push(value);
    }
}